import{_ as t,a,b as i,c as o,d as r,e as n,f as s,g as l,h as m,i as c,j as h}from"./chunks/11.b7m5NYEz.js";import{_ as d,c as u,o as g,ag as p}from"./chunks/framework.iMQzIODh.js";const k=JSON.parse('{"title":"About","description":"","frontmatter":{},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md","lastUpdated":1763376958000}'),f={name:"about/index.md"};function _(b,e,y,v,w,I){return g(),u("div",null,e[0]||(e[0]=[p('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p>Cruise is a powerful, intuitive, and fully-featured TUI (Terminal User Interface) for managing containers. Built with Go and Bubbletea, it offers a visually rich, keyboard-first experience for managing containers, images, volumes, networks, logs and more — all from your terminal.</p><details><summary>Screenshots</summary><p><img src="'+t+'" alt="screenshot"><img src="'+a+'" alt="screenshot"><img src="'+i+'" alt="screenshot"><img src="'+o+'" alt="screenshot"><img src="'+r+'" alt="screenshot"><img src="'+n+'" alt="screenshot"><img src="'+s+'" alt="screenshot"><img src="'+l+'" alt="screenshot"><img src="'+m+'" alt="screenshot"><img src="'+c+'" alt="screenshot"><img src="'+h+`" alt="screenshot"></p></details><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>Manage Lifecycles of Artifacts, currently supports, <ol><li>Containers</li><li>Images</li><li>Networks</li><li>Volumes</li></ol></li><li>Aggregated Detailed statistics of Artifacts</li><li>Aggregated Monitoring and Logging service</li><li>Scanning Images for Vulnerabilities</li><li>...and more to come</li></ul><br><h4 id="planned" tabindex="-1">Planned <a class="header-anchor" href="#planned" aria-label="Permalink to &quot;Planned&quot;">​</a></h4><ul><li>Compose/Project Management</li><li>More Vulnerability Scanners</li><li>Registry management</li><li>Image repository browser</li><li>Alert integration for Monitoring</li><li>And plenty more features?</li></ul><h2 id="why-not-cli" tabindex="-1">Why not CLI? <a class="header-anchor" href="#why-not-cli" aria-label="Permalink to &quot;Why not CLI?&quot;">​</a></h2><p>Ever felt that CLI&#39;s for containerization tools are too lengthy or limited? Find yourself executing commands again and again for simple things? Wrote multiline commands just for a typo to ruin it? Well... Fret no more. Cruise - Is a TUI Container Management Client, fitting easily in your terminal-first dev workflow, while making repetitive work easy and interactive.</p><pre><code>How is cruise different from existing solutions?
</code></pre><p>Existing applications are limited in what they do, they serve as mostly a monitoring service, not a management service let alone a Client.</p><h2 id="why-not-other-tui-alternatives" tabindex="-1">Why not other TUI Alternatives? <a class="header-anchor" href="#why-not-other-tui-alternatives" aria-label="Permalink to &quot;Why not other TUI Alternatives?&quot;">​</a></h2><p>Other TUI Alternatives such as lazydocker or docui (deprecated) are more of a <em>monitoring</em> service than a <em>management</em> application.</p><p>Cruise on the other hand, aims to be a Container Management TUI, allowing management <em>and</em> monitoring of most services. With cruise you can have the benefits of a TUI app without having to deal with the downsides of the CLI. It blends both of them perfectly obtaining the best of both worlds.</p><p>Oh, and did I mention? Cruise looks a lot better... <em>and is also configurable</em>.</p>`,16)]))}const A=d(f,[["render",_]]);export{k as __pageData,A as default};
